def transform(grid):
    """Connect each pair of same-colored markers in a row or column with 3s."""
    # Two marked cells of the same non-background color in a row/column
    # connect with a line of 3s across intervening background cells.
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        for c1 in range(w):
            for c2 in range(c1 + 1, w):
                if grid[r][c1] == grid[r][c2] != bg:
                    for c in range(c1 + 1, c2):
                        if grid[r][c] == bg:
                            out[r][c] = 3
    for c in range(w):
